import {escapeHtml as e,fmt} from './core.js';
const colors=['#285944','#d8a55a','#87a998','#7895ab','#bc8171','#b5be99'];
export function barChart(title,subtitle,rows,{unit='',secondaryLabel=''}={}){
 const maximum=Math.max(1,...rows.flatMap(r=>[Number(r.value)||0,Number(r.secondary)||0]));
 return `<section class="panel chart-panel"><div class="panel-header"><div><h2>${e(title)}</h2><p>${e(subtitle)}</p></div></div><div class="panel-body">${rows.length?`<div class="bar-chart" role="img" aria-label="${e(title)}. ${e(rows.map(r=>`${r.label}: ${fmt(r.value)} ${unit}${r.secondary!==undefined?`, ${secondaryLabel} ${fmt(r.secondary)}`:''}`).join('; '))}">${rows.map(r=>`<div class="chart-bar-row"><div class="chart-bar-label"><span>${e(r.label)}</span><strong>${fmt(r.value)} ${e(unit)}</strong></div><div class="chart-track"><span style="width:${Math.max(0,Number(r.value)/maximum*100)}%"></span></div>${r.secondary!==undefined?`<div class="chart-track secondary"><span style="width:${Math.max(0,Number(r.secondary)/maximum*100)}%"></span></div><small>${e(secondaryLabel)}: ${fmt(r.secondary)} ${e(unit)}</small>`:''}</div>`).join('')}</div>`:'<p class="chart-empty">No data for this selection yet.</p>'}</div></section>`;
}
export function donutChart(title,subtitle,rows){
 const total=rows.reduce((n,r)=>n+Math.max(0,Number(r.value)||0),0);let offset=0;
 const stops=rows.map((r,i)=>{const start=offset;offset+=total?Math.max(0,Number(r.value))/total*100:0;return `${colors[i%colors.length]} ${start}% ${offset}%`;});
 return `<section class="panel chart-panel"><div class="panel-header"><div><h2>${e(title)}</h2><p>${e(subtitle)}</p></div></div><div class="panel-body donut-layout"><div class="donut" role="img" aria-label="${e(title)}: ${e(rows.map(r=>`${r.label} ${r.value}`).join(', '))}" style="background:${total?`conic-gradient(${stops.join(',')})`:'#e5e9df'}"><div><strong>${fmt(total)}</strong><small>Total</small></div></div><ul class="chart-legend">${rows.map((r,i)=>`<li><span class="legend-dot" style="background:${colors[i%colors.length]}"></span><span>${e(r.label)}</span><strong>${fmt(r.value)}</strong><small>${total?Math.round(Number(r.value)/total*100):0}%</small></li>`).join('')}</ul></div></section>`;
}
export function stockRows(levels,unit){return levels.filter(i=>i.is_active&&i.base_unit===unit).sort((a,b)=>Number(a.quantity_on_hand)-Number(b.quantity_on_hand)||a.name.localeCompare(b.name)).slice(0,10).map(i=>({label:i.name,value:Number(i.quantity_on_hand),secondary:Number(i.reorder_point)}));}
export function orderStatusRows(orders){return [['ordered','Awaiting delivery'],['partially_received','Partially received'],['received','Received'],['cancelled','Cancelled']].map(([status,label])=>({label,value:orders.filter(o=>o.status===status).length}));}
export function orderValueByRestaurant(orders,currency){const sums=new Map();for(const o of orders.filter(o=>o.currency===currency&&o.status!=='cancelled')){const key=o.restaurant_id;const prior=sums.get(key)||{label:o.restaurant_name,value:0};prior.value+=Number(o.total_amount)||0;sums.set(key,prior);}return [...sums.values()].sort((a,b)=>b.value-a.value).slice(0,8);}
